<?php
function e($s){return htmlspecialchars((string)$s,ENT_QUOTES,'UTF-8');}
function redirect($u){header("Location: $u");exit;}
function flash($m=null,$t='success'){if($m){$_SESSION['f']=[$m,$t];return;}if(!empty($_SESSION['f'])){[$m,$t]=$_SESSION['f'];unset($_SESSION['f']);return "<div class='alert alert-$t'>".e($m)."</div>";}}
function rating_for($s){$r=db()->prepare("SELECT label,color FROM rating_scales WHERE ? BETWEEN min_score AND max_score LIMIT 1");$r->execute([$s]);return $r->fetch()?:['label'=>'N/A','color'=>'secondary'];}
function audit($who,$act){db()->prepare("INSERT INTO admin_audit_logs(admin_id,action,ip) VALUES(?,?,?)")->execute([$who,$act,$_SERVER['REMOTE_ADDR']??'']);}
function author_hash($id){return hash('sha256',$id.'|'.(getenv('DATABASE_URL')?:'x'));}
function nav_for($t){return ['admin'=>['Dashboard'=>['dashboard.php','speedometer2'],'Employees'=>['employees.php','people'],'Salaries'=>['salaries.php','cash-coin'],'Payroll'=>['payroll.php','wallet2'],'Attendance'=>['attendance.php','calendar-check'],'Leaves'=>['leaves.php','envelope-check'],'Evaluations'=>['evaluations.php','bar-chart'],'Announcements'=>['announcements.php','megaphone'],'Feedback'=>['feedback.php','chat-dots'],'Password'=>['password.php','key']],
'employee'=>['Dashboard'=>['dashboard.php','house'],'Attendance & Leave'=>['leave.php','calendar-check'],'Payslips'=>['payslips.php','receipt'],'Evaluations'=>['evaluations.php','bar-chart'],'Announcements'=>['announcements.php','megaphone'],'Feedback'=>['feedback.php','chat-dots'],'Password'=>['password.php','key']],
'candidate'=>['Assessments'=>['dashboard.php','journal-check'],'Announcements'=>['announcements.php','megaphone'],'Password'=>['password.php','key']]][$t]??[];}
function badge($p){return ['Urgent'=>'danger','Important'=>'warning','Normal'=>'secondary','Open'=>'danger','In Review'=>'warning','Resolved'=>'success','Closed'=>'secondary'][$p]??'secondary';}
function set_att($e,$d,$st,$a,$why){$o=db()->prepare("SELECT status FROM attendance_records WHERE employee_id=? AND att_date=?");$o->execute([$e,$d]);$old=$o->fetchColumn();
db()->prepare("INSERT INTO attendance_records(employee_id,att_date,status,source) VALUES(?,?,?,'manual') ON CONFLICT(employee_id,att_date) DO UPDATE SET status=EXCLUDED.status,source='manual'")->execute([$e,$d,$st]);
db()->prepare("INSERT INTO attendance_audit_logs(employee_id,att_date,old_status,new_status,admin_id,reason) VALUES(?,?,?,?,?,?)")->execute([$e,$d,$old?:null,$st,$a,$why]);}
const ATT=['Present','Half Day','Paid Leave','Unpaid Leave','Weekly Off','Holiday','Absent'];
function money($x){return number_format((float)$x,2);}
function words_inr($n){$n=(int)round($n);if(!$n)return 'Rupees Zero Only';$o=['','One','Two','Three','Four','Five','Six','Seven','Eight','Nine','Ten','Eleven','Twelve','Thirteen','Fourteen','Fifteen','Sixteen','Seventeen','Eighteen','Nineteen'];$t=['','','Twenty','Thirty','Forty','Fifty','Sixty','Seventy','Eighty','Ninety'];
$w=fn($x)=>$x<20?$o[$x]:$t[intdiv($x,10)].($x%10?'-'.$o[$x%10]:'');$s='';
foreach([[10000000,'Crore'],[100000,'Lakh'],[1000,'Thousand'],[100,'Hundred']] as [$d,$l]){if($n>=$d){$q=intdiv($n,$d);$n%=$d;$s.=$w($q).' '.$l.' ';}}
if($n)$s.=$w($n);return 'Rupees '.trim($s).' Only';}
function slip_html($s){$E=json_decode($s['earnings'],true);$D=json_decode($s['deductions'],true);$i=json_decode($s['emp_info'],true);$mn=date('F',mktime(0,0,0,$s['month'],1));
$acc=$i['account']?str_repeat('X',max(0,strlen($i['account'])-4)).substr($i['account'],-4):'—';ob_start();?>
<div id="slip" class="card p-4" style="max-width:820px;background:#fff;color:#111"><div class="d-flex justify-content-between align-items-center border-bottom pb-2 mb-3"><div class="d-flex align-items-center gap-2"><img src="<?=cfg()['base_url']?>/assets/img/logo.svg" width="48"><div><b>AI SQUARE IT SOLUTIONS</b><div class="small text-muted">Build • Evaluate • Grow Together</div></div></div><div class="text-end"><b>Payslip</b><div><?=e($mn.' '.$s['year'])?></div><?php if($s['revision']>0){?><span class="badge text-bg-warning">Revision #<?=$s['revision']?></span><?php }?></div></div>
<div class="row small mb-3"><div class="col-6"><b>Employee ID:</b> <?=e($i['code'])?><br><b>Name:</b> <?=e($i['name'])?><br><b>Joining:</b> <?=e($i['joining'])?></div><div class="col-6"><b>Bank:</b> <?=e($i['bank']?:'—')?><br><b>A/c:</b> <?=e($acc)?><br><b>Paid days:</b> <?=e($s['paid_days'])?> / <?=e($s['days'])?> · <b>LOP:</b> <?=e($s['lop_days'])?></div></div>
<div class="row"><div class="col-6"><table class="table table-sm"><tr><th colspan=2>Earnings</th></tr><?php foreach($E as $k=>$v)echo'<tr><td>'.e($k).'</td><td class="text-end">'.money($v).'</td></tr>';?><tr class="fw-bold"><td>Gross</td><td class="text-end"><?=money($s['gross'])?></td></tr></table></div>
<div class="col-6"><table class="table table-sm"><tr><th colspan=2>Deductions</th></tr><?php foreach($D as $k=>$v)echo'<tr><td>'.e($k).'</td><td class="text-end">'.money($v).'</td></tr>';?><?php if((float)$s['adj_amount']){?><tr><td>One-time adjustment</td><td class="text-end"><?=money($s['adj_amount'])?></td></tr><?php }?><tr class="fw-bold"><td>Total deductions</td><td class="text-end"><?=money($s['total_ded'])?></td></tr></table></div></div>
<div class="border rounded p-2 mb-2"><b>Net Pay: ₹<?=money($s['net'])?></b><div class="small"><?=e(words_inr($s['net']))?></div></div><?php if($s['remarks'])echo'<div class="small">Remarks: '.e($s['remarks']).'</div>';?><div class="small text-muted mt-2">This is a computer-generated payslip and does not require a signature.</div></div>
<button class="btn btn-primary mt-3" onclick="html2pdf().from(document.getElementById('slip')).set({margin:8,filename:'payslip-<?=e($i['code'].'-'.$s['month'].'-'.$s['year'])?>.pdf',jsPDF:{format:'a4'}}).save()">Download PDF</button>
<script src="https://cdnjs.cloudflare.com/ajax/libs/html2pdf.js/0.10.1/html2pdf.bundle.min.js"></script><?php return ob_get_clean();}
